using UnityEngine;
namespace SkiStation { public sealed class VisitorDayPlanDebugUI:MonoBehaviour { private bool show; private void Update(){if(Input.GetKeyDown(KeyCode.F14))show=!show;} private void OnGUI(){if(!show)return; GUILayout.BeginArea(new Rect(12,12,420,260),GUI.skin.window); GUILayout.Label("VISITOR DAY PLANS 1.29"); if(VisitorDayPlanRuntime.I!=null){int ski=0,rest=0,leave=0; foreach(var p in VisitorDayPlanRuntime.I.Plans.Values){if(p.current==VisitorPlanActivity.Ski)ski++;if(p.current==VisitorPlanActivity.Rest)rest++;if(p.current==VisitorPlanActivity.Leave)leave++;} GUILayout.Label($"Real visitors tracked: {VisitorDayPlanRuntime.I.Plans.Count}"); GUILayout.Label($"Ski: {ski} | Rest: {rest} | Leave: {leave}");} GUILayout.EndArea();} } }
